def tiny_main_cell(
    fidelity, half_sync, fp32_acc, in1, in0, out, r0, c1, rt, ct, kb
) -> bool:
    if (
        fidelity.name == "HiFi2"
        and half_sync
        and r0 < 32
        and c1 == 32
        and kb == 1
        and rt * ct == 2
        and out == DataFormat.Float16_b
    ):
        return True
    try:
        key = (
            fidelity.name,
            half_sync,
            fp32_acc,
            _SHORT[in1],
            _SHORT[in0],
            _SHORT[out],
            r0,
            c1,
            rt,
            ct,
            kb,
        )
    except KeyError:
        return False
    return key in _TINY_MAIN


